package fr.mavoixecrite;
import android.app.*;import android.content.Context;import android.widget.*;import java.io.*;import java.util.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowAlertDialog;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={26,35})
public class LibraryTest {
 Context c;
 @Before public void reset(){c=RuntimeEnvironment.getApplication();for(String n:new String[]{DataFile.NAME,DataFile.NAME+".new","phrases-v2.json"})new File(c.getFilesDir(),n).delete();for(String n:new String[]{"options","draft","MainActivity","conversation","voice"})c.getSharedPreferences(n,0).edit().clear().commit();}
 Button button(String s){Button b=AppTest.find(ShadowAlertDialog.getLatestAlertDialog().getWindow().getDecorView(),s);assertNotNull(s,b);return b;}
 @Test public void painSelectionSpeaksWithoutForcingDetails(){try(ActivityController<Activity> ctl=Robolectric.buildActivity(Activity.class).setup()){List<String> said=new ArrayList<>();PhraseLibrary lib=new PhraseLibrary(ctl.get(),said::add,x->{},()->{});lib.pain();assertTrue(said.isEmpty());button("Jambes et pieds ›").performClick();assertTrue(said.isEmpty());button("au genou").performClick();assertEquals("J’ai mal au genou.",said.get(0));button("Le côté ›").performClick();button("du côté gauche").performClick();button("L’intensité de 1 à 10 ›").performClick();button("7 sur 10").performClick();assertEquals("J’ai mal au genou, du côté gauche. Ma douleur est de 7 sur 10.",said.get(2));lib.close();}}
 @Test public void librarySpeaksAndCanPinWithoutSpeakingAgain(){try(ActivityController<Activity> ctl=Robolectric.buildActivity(Activity.class).setup()){List<String> said=new ArrayList<>(),added=new ArrayList<>();PhraseLibrary lib=new PhraseLibrary(ctl.get(),said::add,added::add,()->{});lib.open("Essentiel");button("Mes choix et mes limites ›").performClick();button("Je ne veux pas.").performClick();assertEquals(Arrays.asList("Je ne veux pas."),said);button("Je ne veux pas.").performLongClick();assertEquals(Arrays.asList("Je ne veux pas."),added);assertEquals(1,said.size());lib.close();}}
 @Test public void allSituationsIncludesPainAndMedicationPersonalization(){try(ActivityController<Activity> ctl=Robolectric.buildActivity(Activity.class).setup()){int[] opened={0};PhraseLibrary lib=new PhraseLibrary(ctl.get(),x->{},x->{},()->opened[0]++);lib.open("");assertNotNull(button("Douleur · choisir un endroit ›"));button("Mes médicaments · personnaliser ›").performClick();assertEquals(1,opened[0]);lib.close();}}
 @Test public void curatedPhrasesAreUniqueAndBodyIncludesCommonSites(){Set<String> phrases=new HashSet<>();for(String[] topic:PhraseLibrary.TOPICS)for(int i=2;i<topic.length;i++)assertTrue(topic[i],phrases.add(PhraseStore.normalized(topic[i])));Set<String> sites=new HashSet<>();for(String[] group:PhraseLibrary.BODY)for(int i=1;i<group.length;i++)assertTrue(sites.add(group[i]));assertTrue(sites.containsAll(Arrays.asList("à la gorge","aux dents","au genou","dans le bas du dos","à la poitrine","au ventre","aux parties intimes")));}
 @Test public void optionalPainDetailsNeverInventAttributes(){PhraseLibrary.Pain p=new PhraseLibrary.Pain("à la gorge");assertEquals("J’ai mal à la gorge.",p.sentence());p.sensation="Cela brûle.";p.time="Depuis hier.";assertEquals("J’ai mal à la gorge. Cela brûle. Depuis hier.",p.sentence());}
 @Test public void stopDoesNotCloseTheChoices(){try(ActivityController<Activity> ctl=Robolectric.buildActivity(Activity.class).setup()){int[] stopped={0};PhraseLibrary lib=new PhraseLibrary(ctl.get(),x->{},x->{},()->{},()->stopped[0]++);lib.pain();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();d.getButton(AlertDialog.BUTTON_POSITIVE).performClick();assertEquals(1,stopped[0]);assertTrue(d.isShowing());lib.close();}}
}
